using System.Data;using System.Data.Common;using AiCare.Application;using AiCare.Domain;using AiCare.Infrastructure;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AiCare.Api;[ApiController][Authorize(Policy="Phase1User")][Route("api/messaging/governance")]
public sealed class MessagingGovernanceController(CareDbContext db,ITenantContext tenant,ICurrentUserContext user):ControllerBase
{
 [HttpGet("conversations/{conversationId:guid}")]public async Task<IActionResult> Get(Guid conversationId,CancellationToken t){if(!await Access(conversationId,t))return NotFound();return Ok(new{events=await Rows("select e.id,e.message_id,e.event_type,e.detail,e.actor,e.occurred_at from conversation_message_events e where e.conversation_id=@conversation and e.organization_id=@organization order by e.occurred_at",conversationId,t),escalations=await Rows("select id,message_id,severity,status,owner,response_due_at,reason,acknowledged_at,resolved_at,resolution,created_at from conversation_escalations where conversation_id=@conversation and organization_id=@organization order by created_at desc",conversationId,t)});}
 [HttpPost("messages/{messageId:guid}/fail")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Fail(Guid messageId,StateRequest request,CancellationToken t){var message=await Message(messageId,t);if(message is null)return NotFound();if(string.IsNullOrWhiteSpace(request.Detail))return BadRequest(new{message="Failure reason is required."});var n=await Exec("update conversation_messages set delivery_status='Failed',failure_reason=@detail where id=@message and delivery_status in ('Sent','Delivered')",message.Value,c=>{Add(c,"message",messageId);Add(c,"detail",request.Detail);},t);if(n==0)return Conflict(new{message="Message cannot enter failed state."});await Event(message.Value,messageId,"Failed",request.Detail,t);return Ok();}
 [HttpPost("messages/{messageId:guid}/retry")][Authorize(Roles="CareCoordinator,CareManager,Administrator")]public async Task<IActionResult> Retry(Guid messageId,CancellationToken t){var message=await Message(messageId,t);if(message is null)return NotFound();var n=await Exec("update conversation_messages set delivery_status='Delivered',failure_reason='',retry_count=retry_count+1 where id=@message and delivery_status='Failed'",message.Value,c=>Add(c,"message",messageId),t);if(n==0)return Conflict(new{message="Only failed messages can be retried."});await Event(message.Value,messageId,"Retried","Internal delivery succeeded",t);return Ok();}
 [HttpPost("messages/{messageId:guid}/retention")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Retention(Guid messageId,RetentionRequest request,CancellationToken t){var message=await Message(messageId,t);if(message is null)return NotFound();if(request.RetentionUntil is not null&&request.RetentionUntil<=DateTimeOffset.UtcNow)return BadRequest(new{message="Retention date must be in the future."});await Exec("update conversation_messages set retention_until=@until,legal_hold=@hold where id=@message",message.Value,c=>{Add(c,"message",messageId);Add(c,"until",request.RetentionUntil);Add(c,"hold",request.LegalHold);},t);await Event(message.Value,messageId,"RetentionUpdated",request.LegalHold?"Legal hold applied":"Retention updated",t);return Ok();}
 [HttpPost("escalations/{id:guid}/transition")][Authorize(Roles="CareCoordinator,CareManager,Administrator")]public async Task<IActionResult> Escalate(Guid id,EscalationRequest request,CancellationToken t){var target=request.Action switch{"Acknowledge"=>"Acknowledged","Resolve"=>"Resolved","Reopen"=>"Reopened",_=>""};if(target==""||string.IsNullOrWhiteSpace(request.Detail))return BadRequest(new{message="Valid action and evidence are required."});var n=await Exec("update conversation_escalations set status=@status,acknowledged_at=case when @status='Acknowledged' then now() else acknowledged_at end,resolved_at=case when @status='Resolved' then now() else null end,resolution=case when @status='Resolved' then @detail else resolution end where id=@id and organization_id=@organization",Guid.Empty,c=>{Add(c,"id",id);Add(c,"status",target);Add(c,"detail",request.Detail);},t);if(n==0)return NotFound();Audit("messaging.escalation_transitioned","ConversationEscalation",id);await db.SaveChangesAsync(t);return Ok();}
 private async Task<Guid?> Message(Guid id,CancellationToken t){await using var c=await Command("select m.conversation_id from conversation_messages m join conversations x on x.id=m.conversation_id where m.id=@message and x.organization_id=@organization",Guid.Empty,t);Add(c,"message",id);var v=await c.ExecuteScalarAsync(t);return v is Guid g?g:null;}private async Task<bool> Access(Guid id,CancellationToken t){await using var c=await Command("select exists(select 1 from conversations x join conversation_participants p on p.conversation_id=x.id where x.id=@conversation and x.organization_id=@organization and p.user_id=@user and p.left_at is null)",id,t);Add(c,"user",user.UserId);return Convert.ToBoolean(await c.ExecuteScalarAsync(t));}private async Task Event(Guid conversation,Guid message,string type,string detail,CancellationToken t){await Exec("insert into conversation_message_events(id,message_id,conversation_id,organization_id,event_type,detail,actor) values(@id,@message,@conversation,@organization,@type,@detail,@actor)",conversation,c=>{Add(c,"id",Guid.NewGuid());Add(c,"message",message);Add(c,"type",type);Add(c,"detail",detail);},t);Audit($"messaging.message_{type.ToLowerInvariant()}","ConversationMessage",message);await db.SaveChangesAsync(t);}private async Task<List<Dictionary<string,object?>>> Rows(string sql,Guid id,CancellationToken t){var l=new List<Dictionary<string,object?>>();await using var c=await Command(sql,id,t);await using var r=await c.ExecuteReaderAsync(t);while(await r.ReadAsync(t)){var x=new Dictionary<string,object?>();for(var i=0;i<r.FieldCount;i++)x[Camel(r.GetName(i))]=r.IsDBNull(i)?null:r.GetValue(i);l.Add(x);}return l;}private async Task<int> Exec(string sql,Guid id,Action<DbCommand> bind,CancellationToken t){await using var c=await Command(sql,id,t);bind(c);return await c.ExecuteNonQueryAsync(t);}private async Task<DbCommand> Command(string sql,Guid id,CancellationToken t){var cn=db.Database.GetDbConnection();if(cn.State!=ConnectionState.Open)await cn.OpenAsync(t);var c=cn.CreateCommand();c.CommandText=sql;Add(c,"conversation",id);Add(c,"organization",tenant.OrganizationId);Add(c,"branch",tenant.BranchId??TenantDefaults.BranchId);Add(c,"actor",user.UserName);return c;}private void Audit(string a,string e,Guid id)=>db.AuditEvents.Add(new AuditEvent(Guid.NewGuid(),a,user.UserName,e,id,DateTimeOffset.UtcNow,tenant.OrganizationId,tenant.BranchId??TenantDefaults.BranchId));private static void Add(DbCommand c,string n,object? v){if(c.Parameters.Contains(n))return;var p=c.CreateParameter();p.ParameterName=n;p.Value=v??DBNull.Value;c.Parameters.Add(p);}private static string Camel(string v){var p=v.Split('_');return p[0]+string.Concat(p.Skip(1).Select(x=>char.ToUpperInvariant(x[0])+x[1..]));}
}
public sealed record StateRequest(string Detail);public sealed record RetentionRequest(DateTimeOffset? RetentionUntil,bool LegalHold);public sealed record EscalationRequest(string Action,string Detail);
